import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Multi-Receiver Cooperative Scanning","description":"","frontmatter":{},"headers":[],"relativePath":"integration/multi-receiver.md","filePath":"integration/multi-receiver.md","lastUpdated":null}'),i={name:"integration/multi-receiver.md"};function r(o,e,l,p,d,c){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="multi-receiver-cooperative-scanning" tabindex="-1">Multi-Receiver Cooperative Scanning <a class="header-anchor" href="#multi-receiver-cooperative-scanning" aria-label="Permalink to &quot;Multi-Receiver Cooperative Scanning&quot;">​</a></h1><p>When multiple ES receivers work together, they can cover more spectrum simultaneously — but must avoid listening to the same band redundantly.</p><h2 id="cooperative-team" tabindex="-1">Cooperative team <a class="header-anchor" href="#cooperative-team" aria-label="Permalink to &quot;Cooperative team&quot;">​</a></h2><p>ASTRA supports teams of 1-3 receivers using the <code>CooperativeTeam</code> scheduler.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Receiver A (SmartScan)  →  selects band 7</span></span>
<span class="line"><span>                               ↓</span></span>
<span class="line"><span>                        DND token: &quot;Band 7 is locked&quot;</span></span>
<span class="line"><span>                               ↓</span></span>
<span class="line"><span>Receiver B (SmartScan)  →  removes band 7 from pool</span></span>
<span class="line"><span>                        →  selects band 12 (next best)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="dnd-do-not-disturb-tokens" tabindex="-1">DND (Do Not Disturb) tokens <a class="header-anchor" href="#dnd-do-not-disturb-tokens" aria-label="Permalink to &quot;DND (Do Not Disturb) tokens&quot;">​</a></h2><p>When a SmartScan member has a <strong>confirmed phase-lock</strong> on a target band, it broadcasts a DND token for that band. Other team members completely remove that band from their selection pools.</p><p><strong>Result:</strong> Zero redundancy and perfectly partitioned spectrum coverage.</p><h2 id="benefits" tabindex="-1">Benefits <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;Benefits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Single receiver</th><th>Team of 3</th></tr></thead><tbody><tr><td>Total reward</td><td>1.0×</td><td>~2.7× (near-linear scaling)</td></tr><tr><td>Threat coverage</td><td>95%</td><td>99%+</td></tr><tr><td>Coverage speed</td><td>Slow</td><td>3× faster</td></tr></tbody></table><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>In Operations:</p><ol><li>Set <strong>Team size</strong> to 2 or 3</li><li>Each receiver runs independently with DND de-confliction</li><li>The waterfall shows Receiver A&#39;s perspective; KPIs include team size</li></ol><p>In the API:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /api/live/start?team_size=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&amp;sched_a</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smart-scan</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div>`,15)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
